/**
 * The standard COMMON-LISP symbol database, generated by tools/gen-cl-symbols.lisp
 * from SBCL (arglists, docstrings) and the HyperSpec symbol map (page names).
 */
import raw from '../../data/cl-symbols.json';

export type StdKind =
  | 'function'
  | 'generic-function'
  | 'macro'
  | 'special-operator'
  | 'variable'
  | 'constant'
  | 'class'
  | 'type'
  | 'lambda-list-keyword'
  | 'declaration'
  | 'symbol';

export interface StdSymbol {
  /** Lower-case name. */
  name: string;
  kinds: StdKind[];
  /** Lambda list as printed by SBCL, e.g. "(function list &rest more-lists)". */
  arglist?: string;
  /** Docstrings keyed by what they document ("function", "variable", "type", ...). */
  doc?: Record<string, string>;
  /** HyperSpec page file name, e.g. "f_mapc_.htm". */
  clhs?: string;
}

interface RawData {
  generator: string;
  count: number;
  symbols: Array<{ name: string; kinds: string[]; arglist?: string; doc?: Record<string, string>; clhs?: string }>;
}

const data = raw as unknown as RawData;
const SYMBOLS: StdSymbol[] = data.symbols.map((s) => ({ ...s, kinds: s.kinds as StdKind[] }));
const BY_NAME = new Map<string, StdSymbol>();
for (const symbol of SYMBOLS) BY_NAME.set(symbol.name.toUpperCase(), symbol);

export const GENERATOR = data.generator;

export function lookupStandard(name: string): StdSymbol | undefined {
  return BY_NAME.get(name.toUpperCase());
}

export function allStandard(): readonly StdSymbol[] {
  return SYMBOLS;
}

export const KIND_LABELS: Record<StdKind, string> = {
  function: 'function',
  'generic-function': 'generic function',
  macro: 'macro',
  'special-operator': 'special operator',
  variable: 'variable',
  constant: 'constant',
  class: 'class',
  type: 'type',
  'lambda-list-keyword': 'lambda-list keyword',
  declaration: 'declaration',
  symbol: 'symbol',
};

export function kindLabel(kind: StdKind): string {
  return KIND_LABELS[kind] ?? kind;
}

/** True for macros and special operators: things that take a body or control evaluation. */
export function isOperator(symbol: StdSymbol): boolean {
  return symbol.kinds.includes('macro') || symbol.kinds.includes('special-operator');
}

export function isCallable(symbol: StdSymbol): boolean {
  return symbol.kinds.some((k) => k === 'function' || k === 'generic-function' || k === 'macro' || k === 'special-operator');
}

/** The docstring to show first for a symbol. */
export function primaryDoc(symbol: StdSymbol): string | undefined {
  const doc = symbol.doc;
  if (!doc) return undefined;
  for (const key of ['function', 'macro', 'special-operator', 'variable', 'constant', 'type', 'class']) {
    if (doc[key]) return doc[key];
  }
  const first = Object.values(doc)[0];
  return first;
}

export function hyperspecUrl(symbol: StdSymbol, base: string): string | undefined {
  if (!symbol.clhs) return undefined;
  return base.endsWith('/') ? base + symbol.clhs : `${base}/${symbol.clhs}`;
}
